def handle(app, svc):
    resp = svc.apply(app)

    # API v2 format (current)
    if isinstance(resp, dict) and resp.get("api_version") == 2:
        result = resp.get("result", {})
        outcome = result.get("outcome")
        limit = int(result.get("credit_limit", 0) or 0)
    else:
        # API v1 fallback
        decision = resp.get("decision")
        limit = int(resp.get("limit", 0) or 0)
        if decision == "approve":
            outcome = "approved"
        elif decision == "decline":
            outcome = "declined"
        else:
            outcome = "manual_review"

    # Network referral rule: self_employed applicants with requested_limit
    # above 6000 must go to manual review instead of being issued.
    # A decline stays a decline.
    if outcome == "approved":
        employment = app.get("employment")
        requested_limit = app.get("requested_limit")
        if employment == "self_employed" and requested_limit is not None and requested_limit > 6000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    # manual_review / refer: place in the manual review queue, do not decline.
    return {"action": "queue_review", "limit": 0}

